using Aurora.Core;
using Aurora.Launcher;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
namespace Aurora.Editor;
sealed class ModelLodDraft {public string Key="";public string? Path;public string? ExistingModel;public NativeModel? Model;public double Distance=double.NaN;}
sealed partial class EditorWindow
{
 List<ModelLodDraft> CreateLodDrafts(string script){var result=new List<ModelLodDraft>();foreach(var entry in VehicleLods.Read(script)){string? path=lods.Keys.FirstOrDefault(k=>System.IO.Path.GetFileName(k)==System.IO.Path.GetFileName(entry.Model.Replace('/',System.IO.Path.DirectorySeparatorChar)));result.Add(new(){Key=entry.Key,Path=path,ExistingModel=entry.Model,Model=path==null?null:lods[path],Distance=entry.Distance??double.NaN});}foreach(string path in lods.Keys.Skip(1).Where(p=>!result.Any(d=>d.Path==p))){int i=1;while(result.Any(d=>d.Key=="LOD"+i))i++;result.Add(new(){Key="LOD"+i,Path=path,Model=lods[path]});}return result;}
 void AddLodRow(Panel panel,List<ModelLodDraft> drafts,ModelLodDraft draft,InfoBar error){var row=new Grid{ColumnSpacing=8};row.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new(){Width=new GridLength(120)});row.ColumnDefinitions.Add(new(){Width=GridLength.Auto});var model=new Button{Content=draft.Path==null?(draft.ExistingModel==null?UiLanguage.Text("Выбрать модель LOD…"):System.IO.Path.GetFileName(draft.ExistingModel)):System.IO.Path.GetFileName(draft.Path),HorizontalAlignment=HorizontalAlignment.Stretch};var distance=new NumberBox{Value=draft.Distance,Minimum=1,PlaceholderText=UiLanguage.Text("Дальность, м"),SpinButtonPlacementMode=NumberBoxSpinButtonPlacementMode.Hidden};ToolTipService.SetToolTip(distance,UiLanguage.Text("Дальность, м"));distance.ValueChanged+=(_,_)=>draft.Distance=distance.Value;model.Click+=async(_,_)=>{try{string? path=await Pick(".obj",".nmf");if(path==null)return;var materials=lods.First().Value.Materials;var transform=documentTransform;var imported=await Task.Run(()=>LodModelImport.Read(path,materials,transform));draft.Path=imported.NativePath;draft.Model=imported.Model;model.Content=System.IO.Path.GetFileName(path);}catch(Exception ex){error.Message=ex.Message;error.IsOpen=true;}};row.Children.Add(model);Grid.SetColumn(distance,1);row.Children.Add(distance);var remove=new Button{Content="×",Padding=new Thickness(10,3,10,3)};ToolTipService.SetToolTip(remove,UiLanguage.Text("Удалить LOD"));Microsoft.UI.Xaml.Automation.AutomationProperties.SetName(remove,UiLanguage.Text("Удалить LOD"));remove.Click+=(_,_)=>{drafts.Remove(draft);panel.Children.Remove(row);};Grid.SetColumn(remove,2);row.Children.Add(remove);panel.Children.Add(row);}
 string ValidateLodDrafts(string script,List<ModelLodDraft> drafts){if(drafts.Any(d=>d.ExistingModel!=null&&d.Model==null))throw new InvalidDataException(UiLanguage.Text("Проверьте модели и дальность LOD"));var selected=drafts.Where(d=>d.Path!=null).ToArray();if(selected.Any(d=>d.Model==null||d.Distance is double n&&!double.IsNaN(n)&&(!double.IsFinite(n)||n<=0)))throw new InvalidDataException(UiLanguage.Text("Проверьте модели и дальность LOD"));var paths=selected.Select(d=>d.Path!).Append(lods.Keys.First()).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();if(paths.Select(System.IO.Path.GetFileName).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=paths.Length)throw new InvalidDataException(UiLanguage.Text("У моделей LOD должны быть разные имена файлов"));return VehicleLods.Write(script,VehicleLods.Compact(selected.Select(d=>new VehicleLod(d.Key,System.IO.Path.GetFileName(d.Path!),double.IsNaN(d.Distance)?null:d.Distance))));}
 void ApplyLodDrafts(List<ModelLodDraft> drafts){string primary=lods.Keys.First();var main=lods[primary];var oldModels=new Dictionary<string,NativeModel>(lods);var oldGlass=glassObjects.ToDictionary(p=>p.Key,p=>p.Value);string? current=selectedLod;lods.Clear();glassObjects.Clear();lodChoice.Items.Clear();void Add(string path,NativeModel model){if(lods.ContainsKey(path))return;lods[path]=model;glassObjects[path]=oldModels.TryGetValue(path,out var previous)&&ReferenceEquals(previous,model)?oldGlass.GetValueOrDefault(path)??[]:[];AddLodChoice(path);}Add(primary,main);foreach(var d in drafts.Where(d=>d.Path!=null))Add(d.Path!,d.Model!);SelectLod(current!=null&&lods.ContainsKey(current)?current:primary);}
}
